// Route and authority adapters: the shell is page-oriented, not a CMS form.
import {renderArticle} from '../../hub-cms/render.mjs';
export const mainPages=[['/','Homepage'],['/luthier-hub/','Luthier Hub'],['/components/','Components'],['/wiring-kits/','Wiring Kits'],['/interactive-tools/','Interactive Tools'],['/circuit-forge/','Signal Forge'],['/wiring-generator/','Wiring Diagram Generator'],['/treble-bleed-designer/','Treble Bleed Designer'],['/news/','News'],['/contact/','Contact']].map(([path,title])=>({path,title,authority:'static',editable:false}));
export function pageRoute(value,base='https://apparitioninstruments.co.uk/'){const url=new URL(value,base),origin=new URL(base).origin;if(url.origin!==origin||!/^(?:\/[a-z0-9-]+)*\/$/.test(url.pathname)&&url.pathname!=='/'||/^\/(?:admin|account|basket|checkout|auth|api)(?:\/|$)/.test(url.pathname))throw Error('This destination is outside the website preview.');return url.pathname;}
export function pageLibrary(articles){const result=[...mainPages];for(const article of articles){const c=article.draft;result.push({path:'/luthier-hub/'+c.slug+'/',title:c.title,authority:'article',editable:true,article});}return result;}
export function preparePreview(html,path,document){const parsed=new document.defaultView.DOMParser().parseFromString(html,'text/html');parsed.querySelectorAll('script,iframe,object,embed,base,meta[http-equiv="refresh"]').forEach(e=>e.remove());for(const el of parsed.querySelectorAll('*'))for(const attr of [...el.attributes])if(/^on/i.test(attr.name)||['srcdoc','autofocus'].includes(attr.name))el.removeAttribute(attr.name);parsed.querySelectorAll('form').forEach(e=>{e.removeAttribute('action');e.removeAttribute('method');});parsed.querySelectorAll('input,button,textarea,select').forEach(e=>e.disabled=true);const base=parsed.createElement('base');base.href='https://apparitioninstruments.co.uk'+path;parsed.head.prepend(base);const robots=parsed.createElement('meta');robots.name='robots';robots.content='noindex,nofollow';parsed.head.append(robots);const style=parsed.createElement('style');style.textContent='.reveal{opacity:1!important;transform:none!important}';parsed.head.append(style);return '<!doctype html>'+parsed.documentElement.outerHTML;}
export async function renderPage(page,{request,document,articles}){if(page.authority==='article'){const name=page.article.seed_context?.template_key||page.article.guide_key||'generic',response=await request('/hub-cms/presentation/'+encodeURIComponent(name)+'.json');if(!response.ok)throw Error('Page presentation is unavailable.');const presentation=await response.json(),registry=articles.map(a=>({guide_key:a.guide_key,content:a.draft}));return {html:preparePreview(renderArticle(page.article.draft,presentation,registry,{preview:true}),page.path,document),presentation};}const response=await request(page.path);if(!response.ok)throw Error('This page preview is unavailable.');return {html:preparePreview(await response.text(),page.path,document),presentation:null};}
